// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.sparql;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.UpdateExpr;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.ParsedUpdate;
import org.junit.jupiter.api.Test;

public class TestServiceUpdateExprBuilder {

	/**
	 * The test reproduces a {@link NullPointerException} that is thrown when parsing an update with several update
	 * expressions and one of these contain {@link Service} operator The NPE is thrown because the sourceString is set
	 * to the outermost operation container
	 */
	@Test
	public void testServiceWithMultipleUpdateExpr() {
		SPARQLParser parser = new SPARQLParser();
		String updateStr = "PREFIX family: <http://examples.ontotext.com/family#>\n" +
				"DROP ALL ;\n" +
				"INSERT { family:Alice family:knows family:Bob } " +
				"WHERE { SERVICE <repository:one> { family:Alice family:knows family:Bob } };\n" +
				"INSERT { <urn:bob> <urn:knows> <urn:carol> } " +
				"WHERE { SERVICE <repository:two> { ?s <urn:source:two> ?o } };\n" +
				"INSERT { <urn:carol> <urn:knows> <urn:dave> } " +
				"WHERE { SERVICE <repository:three> { ?s <urn:source:three> ?o } }";
		ParsedUpdate parsed = parser.parseUpdate(updateStr, null);

		List<Service> services = new ArrayList<>();
		for (UpdateExpr updateExpr : parsed.getUpdateExprs()) {
			updateExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(Service service) {
					services.add(service);
					super.meet(service);
				}
			});
		}

		assertEquals(4, parsed.getUpdateExprs().size());
		assertEquals(List.of(
				"family:Alice family:knows family:Bob",
				"?s <urn:source:two> ?o",
				"?s <urn:source:three> ?o"),
				services.stream().map(Service::getServiceExpressionString).toList());
	}
}
